def render_view(key, title):
    kind, heading, rows, insight = VIEWS[key][title]
    e = escape
    if kind == 'assignment':
        body = ('<div class="manager-assignment"><span class="manager-avatar" aria-hidden="true">'
                + e(heading[:1]) + '</span><div><strong>' + e(heading)
                + '</strong><small>Назначенный участник</small></div></div>')
        body += '<div class="manager-notification"><span aria-hidden="true">✓</span><p>' + '<br>'.join(map(e, rows)) + '</p></div>'
    elif kind == 'record':
        body = '<div class="manager-record"><span class="record-mark" aria-hidden="true">01</span><div><strong>' + e(heading) + '</strong><small>' + '<br>'.join(map(e, rows)) + '</small></div><span class="record-dot" aria-hidden="true"></span></div>'
    elif kind in ('checklist', 'work', 'review', 'overview'):
        body = '<ul class="manager-checklist" aria-label="' + e(heading, quote=True) + '">'
        for index, row in enumerate(rows):
            # Checkmarks only denote completed checks. Work/review/overview use numbers.
            mark = '✓' if kind == 'checklist' else str(index + 1)
            body += '<li><span aria-hidden="true">' + mark + '</span>' + e(row) + '</li>'
        body += '</ul>'
    elif kind == 'document':
        body = '<div class="manager-document"><span class="document-fold" aria-hidden="true"></span><strong>' + e(heading) + '</strong><small>' + '<br>'.join(map(e, rows)) + '</small><div class="document-lines" aria-hidden="true"><i></i><i></i><i></i></div></div>'
    elif kind == 'finish':
        body = '<div class="manager-finish"><span aria-hidden="true">✓</span><strong>' + e(heading) + '</strong><small>' + '<br>'.join(map(e, rows)) + '</small></div>'
    else:
        raise ValueError('Unknown manager view type: ' + kind)
    return body + ('<p class="manager-insight">' + e(insight) + '</p>' if key != 'sales' or title != 'Итог' else '')
